package cn.zhuatech.contentai.controller; import cn.zhuatech.contentai.ai.AiProvider; import cn.zhuatech.contentai.common.ApiResponse; import cn.zhuatech.contentai.dto.ContentAiDto.*; import cn.zhuatech.contentai.service.ContentAiService; import cn.zhuatech.contentai.service.ContentReviewService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('DOMAIN_USER','ADMIN')") public class WorkspaceController {private final ContentAiService service;private final AiProvider ai;private final ContentReviewService review;public WorkspaceController(ContentAiService service,AiProvider ai,ContentReviewService review){this.service=service;this.ai=ai;this.review=review;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("反馈提交成功",service.report(id,request));}@PostMapping("/ai-preview") public ApiResponse<AiProvider.AiResult> preview(@RequestBody Map<String,String> body){return ApiResponse.ok(ai.execute(body.getOrDefault("prompt",""),Map.of("mode","demo")));}@PostMapping("/content-review") public ApiResponse<ContentReviewService.ReviewResult> review(@Valid @RequestBody ContentReviewService.ReviewRequest request){return ApiResponse.ok("内容审核完成",review.review(request));}}
